const SNAKE_COMMAND_MENU={"help": {"text": "Snake Media\n\n/request <title> \u2014 request a movie or show.\n/recommend \u2014 find something to watch.\n/status \u2014 My requests, progress and expiry.\n\nChoose a button below. More details: Seasons & expiry or /serverstatus.", "choices": [{"label": "Request", "action": "request"}, {"label": "Recommend", "action": "recommend"}, {"label": "My requests", "action": "status"}, {"label": "Seasons & expiry", "action": "expiry"}, {"label": "Server status", "action": "serverstatus"}]}, "request": {"text": "Send /request followed by a title, or a plain media request.\nExample: /request The Matrix from 1999\n\nReview the poster before confirming. For TV, choose the season(s) you want.", "choices": [{"label": "Recommend", "action": "recommend"}, {"label": "My requests", "action": "status"}, {"label": "Help", "action": "help"}]}, "expiry": {"text": "TV: choose Latest season, All seasons or a specific season, then Confirm. New episodes and future regular seasons are monitored.\n\nMovies: 7 days after import. TV: 30 days per episode after import. Watching can shorten expiry to 7 days; it never extends it.\n\nUse /extend or /keep to choose an existing request. Download cards also have expiry buttons. Include \"keep for 14 days\" or \"keep permanently\" in a new request to change its default.", "choices": [{"label": "Extend", "action": "extend"}, {"label": "Keep permanently", "action": "keep"}, {"label": "My requests", "action": "status"}, {"label": "Help", "action": "help"}]}};
const menus=typeof SNAKE_COMMAND_MENU!=='undefined'?SNAKE_COMMAND_MENU:require('../../src/snake_media/command_menu.json');
function help(){return menus.help.text;}
function prepare(u,botUsername){
 const q=u.callback_query,m=q?.message||u.message;if(!m)return [];
 const d=q?.data?.match(/^snake:([1-9][0-9]{0,15}):([a-z_0-9]+)$/);
 const p={text:q?'confirmation':m.text||'',chatId:m.chat.id,userId:(q?.from||m.from).id,messageId:String(m.message_id),requestedAt:new Date(m.date*1000).toISOString(),action:d?.[2],pendingId:d?.[1],callbackId:q?.id};
 if(q){
  const nav=q.data?.match(/^snake_menu:(help|request|expiry|recommend|status|serverstatus|extend|keep)$/);
  if(nav){const name=nav[1];p.text='/'+name;p.messageId=/^[0-9]+$/.test(String(q.id))?String(q.id):p.messageId;p.requestedAt=new Date().toISOString();if(menus[name]){p.commandReply=menus[name].text;p.menuChoices=menus[name].choices;}}
  return [{json:p}];
 }
 const c=p.text.trim().match(/^\/([a-z][a-z0-9_]*)(?:@([a-z0-9_]+))?(?:\s+([\s\S]*))?$/i);
 if(!c)return [{json:p}];
 if(c[2]&&c[2].toLowerCase()!==String(botUsername).toLowerCase())return [];
 const name=c[1].toLowerCase(),title=(c[3]||'').trim();
 if(name==='request'){
  if(!title||title.length>1600)p.commandReply='Use /request <movie or series title>, up to 1600 characters. Example: /request The Matrix from 1999';
  else p.text='add '+title;
 }else if(name==='serverstatus'){if(title)p.commandReply='Use /serverstatus without a title.';else p.text='/serverstatus';}else if(['help','start'].includes(name)){p.commandReply=help();p.menuChoices=menus.help.choices;}
 else if(!['status','extend','keep','recommend'].includes(name))p.commandReply='Unknown command. Use /request <title>, /status or /help.';
 return [{json:p}];
}
if(typeof module!=='undefined')module.exports={prepare,help};

return prepare($json,"SnakeMediaRequestBot");

// Media presentation metadata derived from native application snapshots.
const LOCAL_JELLYFIN_BASE="http://192.168.1.10:8096";
function jellyfinLinks(item,remoteBase,localBase=''){
 if(!item?.Id)return {};
 const suffix='/web/index.html#!/details?id='+encodeURIComponent(item.Id);
 const result={jellyfinUrl:remoteBase+suffix};
 if(localBase&&localBase!==remoteBase)result.localJellyfinUrl=localBase+suffix;
 return result;
}
function progress(q){
 const total=Number(q.size),left=Number(q.sizeleft);let parts=[];
 if(Number.isFinite(total)&&total>0&&Number.isFinite(left)&&left>=0)parts.push(Math.round(Math.max(0,Math.min(1,(total-left)/total))*100)+'%');
 if(typeof q.timeleft==='string'&&/^[0-9:. ]{1,30}$/.test(q.timeleft))parts.push('ETA '+q.timeleft);
 const quality=q.quality?.quality?.name;if(typeof quality==='string')parts.push(quality.slice(0,100));
 return parts.join(' · ');
}
function poster(media){return (media.images||[]).find(x=>x.coverType==='poster'&&typeof x.remoteUrl==='string'&&/^https:\/\/(image\.tmdb\.org|artworks\.thetvdb\.com)\//.test(x.remoteUrl))?.remoteUrl;}
function completion(c,records,item,media){
 const key=`file:${c.request.mediaType}:${c.request.mediaId}:${c.fileId}`;
 let v;try{v=JSON.parse(records.find(x=>x.key===key)?.payloadJson||'null');}catch{}
 let expiryText='Expiry check pending.';
 if(v&&v.state==='tracked'&&'/data'+v.path===c.jellyfinPath&&Date.parse(v.importedAt)===Date.parse(c.importedAt)&&Number.isFinite(Date.parse(v.checkedAt))){
  if(v.identityProtected||!v.expiresAt||['protected claim','unclaimed','unclaimed episode in shared file'].includes(v.reason))expiryText='Protected / kept permanently; no automatic deletion.';
  else if(Number.isFinite(Date.parse(v.expiresAt)))expiryText='Expiry: '+new Intl.DateTimeFormat('en-US',{timeZone:'America/Los_Angeles',month:'short',day:'numeric',year:'numeric',hour:'numeric',minute:'2-digit',timeZoneName:'short'}).format(new Date(v.expiresAt));
  if(Date.now()-Date.parse(v.checkedAt)>30*60000)expiryText+=' (last retention check is stale; dates may change).';
 }
 return {posterUrl:poster(media),...jellyfinLinks(item,'http://100.100.100.100:8096',LOCAL_JELLYFIN_BASE),expiryText,quality:c.quality};
}
function feedback(r){
 if(r.status==='added')return '✅ Request accepted: '+r.title+'\n'+(r.searchStarted?'🔎 Search started. Checking for an acceptable release; use /status for download updates.':'Search has not been confirmed; use /status for updates.');
 if(r.status==='already_added')return '✅ '+r.title+' is already registered. Use /status to see availability, download progress and expiry.';
 if(r.status==='notice'&&r.actionAccepted===true&&/\bSearch started\b/i.test(r.text||''))return '✅ Request accepted.\n'+r.text+'\nUse /status for download quality, progress and expiry.';
 return r.text;
}
function progressNotice(r,snapshot,notices,now){
 if(!r.requestKey||r.userId==='1'||!['discord','telegram'].includes(r.source)||!Number.isFinite(Date.parse(r.requestedAt)))return null;
 const own=notices.filter(n=>n.requestKey===r.requestKey);
 if(own.some(n=>!n.notificationKey.includes(':progress:')))return null;
 const text=String(snapshot.text||'');
 const downloading=snapshot.progressState==='downloading';
 const waiting=snapshot.progressState==='waiting'&&now-Date.parse(r.requestedAt)>=10*60000;
 if(!downloading&&!waiting)return null;
 const state=downloading?'downloading':'no-release',notificationKey=r.requestKey+':progress:'+state;
 if(own.some(n=>n.notificationKey===notificationKey))return null;
 const label=downloading?'⬇️ Download started.':'🔎 No acceptable release is downloading yet. Snake Media will continue looking.';
 const payload={text:(label+'\n\n'+text).slice(0,1800),userId:r.userId,messageId:r.messageId,retentionControls:false};
 return {notificationKey,requestKey:r.requestKey,fileKey:'progress:'+state,source:r.source,destinationId:r.destinationId,payloadJson:JSON.stringify(payload),state:'pending',attempts:0,nextAttemptAt:new Date(now).toISOString(),deliveredAt:null,deliveredMessageId:''};
}
function completionExists(c,notices){
 const key=c.request.requestKey+':'+(c.mediaType==='tv'?'tv-ready':c.fileKey);
 return notices.some(r=>r.notificationKey===key || (c.mediaType==='tv'&&r.requestKey===c.request.requestKey&&r.state==='delivered'&&!String(r.notificationKey).includes(':progress:')));
}
function scopedQueue(requests,episodes,queue,records=[]){
 const r=requests[0];
 if(r.mediaType==='movie')return queue.filter(q=>q.movieId===Number(r.mediaId));
 const ids=new Set(requests.flatMap(x=>JSON.parse(x.episodeIdsJson||'[]')).map(String));
 const keys=new Set(requests.map(x=>'request:'+x.requestKey));
 for(const row of records){
  if(!keys.has(row.key))continue;
  const saved=JSON.parse(row.payloadJson);
  for(const id of saved.episodeIds||[])ids.add(String(id));
 }
 const seasons=new Set(episodes.filter(e=>ids.has(String(e.id))&&Number.isSafeInteger(e.seasonNumber)&&e.seasonNumber>0).map(e=>e.seasonNumber));
 return queue.filter(q=>q.seriesId===Number(r.mediaId)&&(q.episodeId?ids.has(String(q.episodeId)):Number.isSafeInteger(q.seasonNumber)&&seasons.has(q.seasonNumber)));
}
if(typeof module!=='undefined')module.exports={progress,poster,completion,feedback,progressNotice,completionExists,scopedQueue,jellyfinLinks};

const r={...$json,text:feedback($json)||$json.text};if(r.noticeId){r.pendingId=r.noticeId;r.choices=[{label:'Extend 7 days',action:'notice_7'},{label:'Extend 30 days',action:'notice_30'},{label:'Keep permanently',action:'notice_keep'}];}const p=$('Prepare Request').first().json;let text=r.text|| (r.status==='not_found'?'🔎 No matching title was found. Try including the year.':'⚠️ Unable to process that request. Please try again.');return [{json:{...r,ownerId:String(p.userId),chatId:p.chatId,replyText:text.replace(/&/g,'&amp;').replace(/</g,'&lt;').replace(/>/g,'&gt;'),keyboard:{rows:(r.choices||[]).map(c=>({row:{buttons:[{text:c.label,additionalFields:{callback_data:'snake:'+r.pendingId+':'+c.action}}]}}))}}}];

// Read-only status projection. Never calculates or changes retention policy.
function command(text){const m=typeof text==='string'&&text.trim().match(/^\/?status(?:@[A-Za-z0-9_]+)?(?:\s+(.*))?$/i);return m?(m[1]||'').trim().slice(0,200):null;}
function select(rows,actor){
 if(!['discord','telegram'].includes(actor.source)||typeof actor.userId!=='string'||!/^\d+$/.test(actor.userId))throw new Error('Invalid status actor');
 const query=String(actor.query||'').toLowerCase();const groups=new Map();
 for(const r of [...rows].sort((a,b)=>Date.parse(b.requestedAt)-Date.parse(a.requestedAt))){
  if(r.source!==actor.source||r.userId!==actor.userId||r.userId==='1'||r.state!=='registered'||!r.requestKey||!['movie','tv'].includes(r.mediaType)||!/^\d+$/.test(String(r.mediaId))||!String(r.title).toLowerCase().includes(query))continue;
  const key=r.mediaType+':'+r.mediaId;if(!groups.has(key))groups.set(key,[]);groups.get(key).push(r);
 }
 const values=[...groups.values()];
 if(!values.length)return [{notice:query?'No requests of yours match that title.':'No requests found for your account on this platform.'}];
 if(query&&values.length>1)return [{notice:'Several matches. Use status with a more specific title:\n'+values.slice(0,8).map(rs=>'• '+rs[0].title.slice(0,100)).join('\n')}];
 return values.slice(0,3).map(requests=>({requests}));
}
function dateLabel(stamp){return new Intl.DateTimeFormat('en-US',{timeZone:'America/Los_Angeles',month:'short',day:'numeric',year:'numeric',hour:'numeric',minute:'2-digit',timeZoneName:'short'}).format(new Date(stamp));}
function describe({requests,records,media,episodes,queue,library,now}){
 const r=requests[0],title=String(r.title).replace(/[\r\n]/g,' ').slice(0,100),header=(r.mediaType==='movie'?'🎬 ':'📺 ')+title;
 if(!media||media.id!==Number(r.mediaId))return header+'\nNo longer listed in '+(r.mediaType==='movie'?'Radarr.':'Sonarr.');
 const saved=new Map(records.filter(x=>x.key).map(x=>[x.key,JSON.parse(x.payloadJson)]));
 const ids=new Set(requests.flatMap(x=>JSON.parse(x.episodeIdsJson||'[]').map(String)));
 for(const request of requests){const profile=saved.get('request:'+request.requestKey);if(profile)for(const id of profile.episodeIds||[])ids.add(String(id));}
 const items=r.mediaType==='movie'?[{id:r.mediaId,file:media.movieFile,release:media.digitalRelease||media.physicalRelease||media.inCinemas}]:episodes.filter(e=>ids.has(String(e.id))).map(e=>({...e,file:e.episodeFile,release:e.airDateUtc}));
 const paths=new Set(library.filter(x=>x.Id&&x.Path).map(x=>x.Path));
 const counts={available:0,imported:0,downloading:0,queued:0,unreleased:0,waiting:0,removed:0};const files=new Map();
 for(const item of items){
  if(item.file?.id){files.set(item.file.id,item.file);counts[paths.has('/data'+item.file.path)?'available':'imported']++;continue;}
  const q=queue.find(q=>r.mediaType==='movie'?q.movieId===Number(r.mediaId):q.seriesId===Number(r.mediaId)&&(q.episodeId===item.id||(!q.episodeId&&q.seasonNumber===item.seasonNumber)));
  if(q){counts[String(q.status).toLowerCase()==='downloading'?'downloading':'queued']++;continue;}
  const deleted=r.mediaType==='tv'&&[...saved.entries()].some(([key,v])=>key.startsWith('file:tv:'+r.mediaId+':')&&v.state==='deleted'&&(v.episodeIds||[]).includes(String(item.id)));
  counts[deleted?'removed':Date.parse(item.release)>now?'unreleased':'waiting']++;
 }
 let status;
 if(r.mediaType==='movie')status=counts.available?'✅ Available in Jellyfin':counts.imported?'📥 Imported; waiting for Jellyfin':counts.downloading?'⬇️ Downloading':counts.queued?'⏳ In download queue / awaiting import':counts.unreleased?'📅 Awaiting release':'🔎 Waiting for a release';
 else {const labels={available:'available in Jellyfin',imported:'imported; waiting for Jellyfin',downloading:'downloading',queued:'queued / awaiting import',unreleased:'awaiting release',waiting:'waiting for a release',removed:'previously expired'};status=Object.entries(counts).filter(([,v])=>v).map(([k,v])=>v+' '+labels[k]).join(' · ')||'Episode metadata pending';}
 let protectedCount=0,pending=0,earliest=null,oldest=Infinity,deferred=0;
 for(const file of files.values()){
  const v=saved.get(`file:${r.mediaType}:${r.mediaId}:${file.id}`);
  if(!v||v.state!=='tracked'||v.path!==file.path||Date.parse(v.importedAt)!==Date.parse(file.dateAdded)||!Number.isFinite(Date.parse(v.checkedAt))){pending++;continue;}
  oldest=Math.min(oldest,Date.parse(v.checkedAt));
  if(v.identityProtected||!v.expiresAt||v.reason==='protected claim'||v.reason==='unclaimed'||v.reason==='unclaimed episode in shared file'){protectedCount++;continue;}
  if(!Number.isFinite(Date.parse(v.expiresAt))){pending++;continue;}
  earliest=Math.min(earliest??Infinity,Date.parse(v.expiresAt));
  if(v.reason==='currently playing or unresolved active session')deferred++;
 }
 const lines=[header,status];
 if(earliest!==null)lines.push((r.mediaType==='tv'?'Next episode expiry: ':'Expiry: ')+dateLabel(earliest)+(earliest<=now?' (due; cleanup pending)':''));
 if(protectedCount)lines.push(protectedCount+' protected '+(protectedCount===1?'file':'files')+' — no automatic deletion.');
 if(pending)lines.push('Expiry check pending for '+pending+' '+(pending===1?'file.':'files.'));
 if(!files.size){const days=[...new Set(requests.map(x=>x.retentionDays))];lines.push(days.includes(null)?'Permanent/protected request.':days.length===1?`Expiry starts after import (${days[0]} days${r.mediaType==='tv'?' per episode':''}).`:'Expiry starts after import; multiple retention choices apply.');}
 if(Number.isFinite(oldest))lines.push('Retention checked '+dateLabel(oldest)+(now-oldest>30*60000?' — stale; dates may change.':'.'));
 if(deferred)lines.push('Cleanup deferred for active playback.');
 if(r.mediaType==='tv'&&requests.some(x=>saved.has('request:'+x.requestKey)))lines.push('Future regular seasons monitored.');
 return lines.join('\n');
}
if(typeof module!=='undefined')module.exports={command,select,describe};

const p=$('Prepare Request').first().json;return [{json:{...p,statusQuery:command(p.text)}}];

// Confirmation and immutable retention amendments. No service calls.
function parseChange(text){
 if(typeof text!=='string')return null;
 const input=text.trim();if(!/^\/?(?:extend|keep)(?:@[A-Za-z0-9_]+)?(?:\s|$)/i.test(input))return null;
 const bare=input.match(/^\/?(extend|keep)(?:@[A-Za-z0-9_]+)?$/i);
 if(bare)return {operation:bare[1].toLowerCase()==='keep'?'permanent':'extend',guided:true};
 let m=input.match(/^\/?extend(?:@[A-Za-z0-9_]+)?\s+(.+?)\s+([0-9]+)\s+days?$/i);
 if(m&&Number(m[2])>=1&&Number(m[2])<=3650)return {operation:'extend',query:m[1].trim(),days:Number(m[2])};
 m=input.match(/^\/?keep(?:@[A-Za-z0-9_]+)?\s+(.+?)\s+permanently$/i);
 if(m)return {operation:'permanent',query:m[1].trim()};
 return {error:'Use extend <title> 7 days (1–3650 whole days), or keep <title> permanently.'};
}
function titleKey(text){
 return String(text).normalize('NFKD').replace(/\p{M}/gu,'').toLowerCase()
  .replace(/&/g,' and ').replace(/['’]/g,'').replace(/[^\p{L}\p{N}]+/gu,' ').trim();
}
function prepareChange(actor,rows){
 if(!['discord','telegram'].includes(actor.source)||typeof actor.userId!=='string'||!/^\d+$/.test(actor.userId))throw Error('Invalid actor');
 const parsed=parseChange(actor.text);if(!parsed||parsed.error)return {notice:parsed?.error||'Not a retention command.'};
 const owned=rows.filter(r=>r.source===actor.source&&r.userId===actor.userId&&r.userId!=='1'&&r.state==='registered'&&r.requestKey&&(!actor.requestKey||r.requestKey===actor.requestKey)&&['movie','tv'].includes(r.mediaType)&&/^\d+$/.test(String(r.mediaId))&&typeof r.title==='string'&&r.title.trim());
 const query=titleKey(parsed.query||'');
 let matches=parsed.guided?owned:query?owned.filter(r=>titleKey(r.title).includes(query)):[];
 if(!parsed.guided&&matches.some(r=>titleKey(r.title)===query))matches=matches.filter(r=>titleKey(r.title)===query);
 const keys=new Set(matches.map(r=>r.mediaType+':'+r.mediaId));
 if(!matches.length)return {notice:'No requests of yours match that title on this platform.'};
 if(parsed.guided||keys.size!==1){
  const candidates=[...keys].map(key=>{const rs=matches.filter(r=>r.mediaType+':'+r.mediaId===key),r=rs[0];return {source:actor.source,userId:actor.userId,mediaType:r.mediaType,mediaId:String(r.mediaId),title:r.title.slice(0,150),requestKeys:[...new Set(rs.map(r=>r.requestKey))]};});
  candidates.sort((a,b)=>a.title.localeCompare(b.title)||a.mediaId.localeCompare(b.mediaId));
  return {guide:{operation:parsed.operation,...(parsed.days?{days:parsed.days}:{}),candidates,page:0}};
 }
 const r=matches[0];return {change:{...parsed,source:actor.source,userId:actor.userId,requestKeys:[...new Set(matches.map(r=>r.requestKey))],mediaType:r.mediaType,mediaId:String(r.mediaId),title:String(r.title).slice(0,150)}};
}
function planChange(change,requests,decisions,records,{pendingId,now}){
 if(!['extend','permanent'].includes(change.operation)||!Array.isArray(change.requestKeys)||!change.requestKeys.length||!/^\d+$/.test(String(pendingId))||!Number.isFinite(now))throw Error('Invalid amendment');
 if(change.operation==='extend'&&(!Number.isInteger(change.days)||change.days<1||change.days>3650))throw Error('Invalid duration');
 const selected=change.requestKeys.map(key=>requests.find(r=>r.requestKey===key));
 if(selected.some(r=>!r||r.state!=='registered'||r.mediaType!==change.mediaType||String(r.mediaId)!==change.mediaId||r.source!==change.source||r.userId!==change.userId))throw Error('Request ownership changed');
 const existing=records.filter(r=>r.key==='change:'+pendingId);
 if(existing.length>1)throw Error('Duplicate amendment');
 if(existing.length){const e=JSON.parse(existing[0].payloadJson);if(e.source!==change.source||e.userId!==change.userId||e.operation!==change.operation||e.mediaId!==change.mediaId||e.mediaType!==change.mediaType)throw Error('Amendment collision');return e;}
 const result={version:1,pendingId:String(pendingId),operation:change.operation,source:change.source,userId:change.userId,requestKeys:change.requestKeys,mediaType:change.mediaType,mediaId:change.mediaId,title:change.title,createdAt:new Date(now).toISOString(),files:[]};
 if(change.operation==='permanent')return result;
 const ids=new Set(selected.flatMap(r=>JSON.parse(r.episodeIdsJson||'[]').map(String)));
 for(const row of records)if(selected.some(r=>row.key==='request:'+r.requestKey))for(const id of JSON.parse(row.payloadJson).episodeIds||[])ids.add(String(id));
 for(const d of decisions){
  if(change.mediaType==='tv'&&!(d.episodeIds||[]).some(id=>ids.has(String(id))))continue;
  if(d.state!=='tracked'||d.identityProtected||!d.expiresAt||!Number.isFinite(Date.parse(d.expiresAt))||!Number.isFinite(Date.parse(d.importedAt))||!Number.isSafeInteger(d.fileId)||typeof d.path!=='string')continue;
  const minimumExpiry=new Date(Math.max(now,Date.parse(d.expiresAt))+change.days*86400000).toISOString();
  result.files.push({fileId:d.fileId,path:d.path,importedAt:d.importedAt,minimumExpiry});
 }
 if(!result.files.length)return {notice:'No imported files with a timed expiry need extending. Files already protected stay protected; upcoming episodes keep their existing retention.'};
 return result;
}
function guideAction(row,actor,now){
 if(!row||['source','userId','destinationId'].some(k=>row[k]!==actor[k]))throw Error('Not your request');
 if(row.state!=='preview'||!Number.isFinite(Date.parse(row.expiresAt))||Date.parse(row.expiresAt)<=now)throw Error('Expired or handled');
 const ctx=JSON.parse(row.contextJson),g=ctx.retentionGuide;
 if(!g||!Array.isArray(g.candidates)||!['extend','permanent'].includes(g.operation))throw Error('Invalid guide');
 if(actor.action==='cancel')return {state:'cancelled',choice:'cancel',contextJson:row.contextJson};
 const page=actor.action.match(/^retpage_([0-9]{1,3})$/),title=actor.action.match(/^rettitle_([0-9]{1,4})$/);
 if(page&&g.selected===undefined&&Number(page[1])*8<g.candidates.length)g.page=Number(page[1]);
 else if(title&&g.selected===undefined&&Number(title[1])>=g.page*8&&Number(title[1])<(g.page+1)*8&&g.candidates[Number(title[1])])g.selected=Number(title[1]);
 else if(/^retdays_(7|30)$/.test(actor.action)&&g.selected!==undefined&&g.operation==='extend'&&!g.days)g.days=Number(actor.action.slice(8));
 else throw Error('Stale or invalid guide choice');
 if(g.selected!==undefined&&(g.operation==='permanent'||g.days)){
  ctx.retentionChange={...g.candidates[g.selected],operation:g.operation,...(g.operation==='extend'?{days:g.days}:{})};delete ctx.retentionGuide;
 }
 return {state:'preview',choice:actor.action,contextJson:JSON.stringify(ctx)};
}
function changeCard(row){
 if(row.version)return row;
 const ctx=JSON.parse(row.contextJson),c=ctx.retentionChange,g=ctx.retentionGuide;
